import itertools, json, sys, time
sys.path.insert(0,'/app')
from instrument import solve

def build(seqs):
    threads=[]
    val=1
    for seq in seqs:
        th=[]
        for k in seq:
            if k=='s': th.append(["store",0,1,val]); val+=1
            elif k=='x': th.append(["xchg",0,1,val]); val+=1
            else: th.append(["load",0,1])
        threads.append(th)
    return {"memory":[0],"threads":threads}

best_no=(0,None); best_st=(0,None)
t0=time.time()
# lengths 4,3,3
for s0 in itertools.product('sxl',repeat=4):
  for s1 in itertools.product('sxl',repeat=3):
    for s2 in itertools.product('sxl',repeat=3):
        req=build([s0,s1,s2])
        r=solve(req)
        no=len(r['outcomes']); st=r['_states']
        if no>best_no[0]: best_no=(no,json.dumps(req))
        if st>best_st[0]: best_st=(st,json.dumps(req))
print("elapsed",time.time()-t0)
print("best outcomes",best_no)
print("best states",best_st)
